package ui

import "encoding/base64"

var presetImagesBase64 = map[string]string{
	"local-protection":   "",
	"workstation":        "",
	"on-demand":          "",
	"cloud-local":        "",
}

func PresetImageBytes(id string) ([]byte, bool) {
	b64, ok := presetImagesBase64[id]
	if !ok {
		return nil, false
	}
	b, err := base64.StdEncoding.DecodeString(b64)
	return b, err == nil
}
